SELECT t.*, m.symbol AS etfName
FROM etf_ta_indicator t
LEFT JOIN etf_security_master m ON t.etf_code = m.etf_code


        AND t.etf_code LIKE CONCAT(#{keyword}, '%')


        AND m.symbol LIKE CONCAT(#{etfName}, '%')


        AND t.period IN

            #{p}



        AND t.trade_time >= #{tradeTimeDate}
        AND t.trade_time < DATE_ADD(#{tradeTimeDate}, INTERVAL 1 DAY)


        AND t.signal_trend_long = #{signalTrendLong}


        AND t.is_macd_red = #{isMacdRed}


        AND t.macd_hist_direction = #{macdHistDirection}


        AND t.is_sar_bullish = #{isSarBullish}


        AND t.sar_trend = #{sarTrend}


        AND t.signal_momentum_long = #{signalMomentumLong}


        AND t.signal_warning = #{signalWarning}



    ORDER BY t.etf_code
    ORDER BY m.symbol
    ORDER BY t.period
    ORDER BY t.trade_time
    ORDER BY t.macd
    ORDER BY t.is_macd_red
    ORDER BY t.macd_hist_direction
    ORDER BY t.sar_value
    ORDER BY t.is_sar_bullish
    ORDER BY t.sar_trend
    ORDER BY t.signal_trend_long
    ORDER BY t.signal_momentum_long
    ORDER BY t.signal_warning
    ORDER BY t.etf_code DESC, t.trade_time DESC, t.period



         ASC
         DESC


LIMIT #{offset}, #{size}

SELECT COUNT(1)
FROM etf_ta_indicator t
LEFT JOIN etf_security_master m ON t.etf_code = m.etf_code


        AND t.etf_code LIKE CONCAT(#{keyword}, '%')


        AND m.symbol LIKE CONCAT(#{etfName}, '%')


        AND t.period IN

            #{p}



        AND t.trade_time >= #{tradeTimeDate}
        AND t.trade_time < DATE_ADD(#{tradeTimeDate}, INTERVAL 1 DAY)


        AND t.signal_trend_long = #{signalTrendLong}


        AND t.is_macd_red = #{isMacdRed}


        AND t.macd_hist_direction = #{macdHistDirection}


        AND t.is_sar_bullish = #{isSarBullish}


        AND t.sar_trend = #{sarTrend}


        AND t.signal_momentum_long = #{signalMomentumLong}


        AND t.signal_warning = #{signalWarning}
